 import { arredondar } from '../util/numero';

+/**
+ * @description Calcula o valor de cada parcela de uma proposta sem juros.
+ * @param total valor total em reais
+ * @param n número de parcelas
+ */
+export function valorParcela(total: number, n: number): number {
+  return arredondar(total / n);
+}
+
 export function totalComEntrada(total: number, entrada: number): number {
   return total - entrada;
