diff --git a/src/leads/rotas.ts b/src/leads/rotas.ts
--- a/src/leads/rotas.ts
+++ b/src/leads/rotas.ts
@@ -1,4 +1,17 @@
 import { Router } from 'express';
+import { body, validationResult } from 'express-validator';
 import { criarLead } from './servico';

 const router = Router();

+router.post(
+  '/leads',
+  body('nome').isString().trim().notEmpty(),
+  body('telefone').isMobilePhone('pt-BR'),
+  async (req, res) => {
+    const erros = validationResult(req);
+    if (!erros.isEmpty()) return res.status(422).json({ erros: erros.array() });
+    const lead = await criarLead(req.body);
+    return res.status(201).json(lead);
+  },
+);
+
 export default router;
